// Lot 1 — validation d'entrée. Toute incohérence d'entité ou de workspace est
// rejetée immédiatement, avant la moindre écriture ou le moindre token.
const item = $input.first().json;
const body = item.body || {};
const headers = item.headers || {};

const receivedSignature = headers['x-kredo-signature'] || headers['X-KREDO-Signature'] || '';
const expectedSignature = 'sha256=' + (item.computedSignature || '');
if (!receivedSignature || receivedSignature !== expectedSignature) {
  throw new Error('Signature HMAC invalide (X-KREDO-Signature) — requête rejetée');
}

const required = ['runId', 'workflowId', 'entityType', 'entityId', 'workspaceId', 'userId', 'callbackUrl'];
for (const field of required) {
  if (!body[field]) throw new Error(`Champ requis manquant dans le payload : ${field}`);
}

if (body.entityType !== 'company') {
  throw new Error('intel-030-account-knowledge requiert entityType="company"');
}

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
for (const field of ['runId', 'entityId', 'workspaceId']) {
  if (!UUID.test(String(body[field]))) throw new Error(`UUID invalide pour ${field}`);
}

// companyId, s'il est envoyé séparément, doit désigner la même entité.
if (body.companyId && body.companyId !== body.entityId) {
  throw new Error('Incohérence d\'entité : companyId différent de entityId');
}

return [{
  json: {
    runId: body.runId,
    workflowId: body.workflowId,
    workspaceId: body.workspaceId,
    userId: body.userId,
    companyId: body.entityId,
    callbackUrl: body.callbackUrl,
    startedAtMs: Date.now(),
  }
}];

// Préparation DÉTERMINISTE du contexte (aucun LLM ici).
// Sépare explicitement ce qui est canonique, ce qui est vérifié, ce qui est
// relationnel, et ce qui est FOLIO — ce dernier restant isolé comme legacy NON
// SOURCÉ : il peut orienter une recherche, jamais devenir un Claim.
const upstream = $('Validate Entity').first().json;
const raw = $input.first().json;
const ctx = (raw && raw.company) ? raw : (Array.isArray(raw) ? raw[0] : (raw && raw.data) || {});

if (!ctx || !ctx.company || !ctx.company.id) {
  throw new Error('Contexte compte introuvable (RPC get_account_knowledge_context vide)');
}
if (ctx.company.id !== upstream.companyId) {
  throw new Error('Incohérence d\'entité : le contexte ne correspond pas au compte demandé');
}

function txt(v) {
  if (v === null || v === undefined) return null;
  const t = String(v).replace(/\s+/g, ' ').trim();
  return t.length > 0 ? t : null;
}

const c = ctx.company;
const canonical = {
  id: c.id,
  name: txt(c.name),
  legal_name: txt(c.legal_name),
  hq_location: txt(c.hq_location),
  revenue: txt(c.revenue),
  employee_count: (typeof c.employee_count === 'number') ? c.employee_count : null,
  size_band: txt(c.size_band),
  website: txt(c.website),
  sector: txt(c.sector),
  segment: txt(c.segment),
  description: txt(c.description),
  lifecycle_status: txt(c.lifecycle_status),
};

// Faits VÉRIFIÉS uniquement (verified_at non nul) — un fait courant mais jamais
// vérifié n'est pas approuvé, seulement "pas périmé" (même règle que Lot 0).
const verifiedFacts = (ctx.accountFacts || []).filter((f) => f && f.verified_at);
const factSources = ctx.factSources || [];
const factSourceLinks = ctx.factSourceLinks || [];

const relational = {
  contacts: ctx.contacts || [],
  recentInteractions: ctx.recentInteractions || [],
  opportunities: ctx.opportunities || [],
  missions: ctx.missions || [],
  signals: ctx.signals || [],
};

// FOLIO — jamais fusionné au reste, jamais présenté comme sourcé.
const folioLegacy = {
  analysisData: ctx.folioAnalysisData || null,
  sectorAnalysis: ctx.folioSectorAnalysis || null,
};
const hasFolio = !!(folioLegacy.analysisData && Object.keys(folioLegacy.analysisData).length > 0);

// ── Cibles de recherche externe : uniquement le MANQUANT ou le PÉRIMÉ ───────
const STALE_AFTER_DAYS = 365;
const nowMs = Date.now();
const verifiedByType = new Map();
for (const f of verifiedFacts) {
  verifiedByType.set(f.fact_type, f);
}
// « Périmé » suppose une vérification qui a existé et qui a vieilli. Une valeur
// renseignée mais jamais vérifiée n'est PAS périmée : elle est non vérifiée, et
// la vérification est un geste humain (D-4) qu'on ne déclenche pas d'office.
// Sans cette distinction, tout champ renseigné déclencherait une recherche
// externe à chaque run — coût et bruit garantis, pour une donnée déjà présente.
function isStale(factType) {
  const f = verifiedByType.get(factType);
  if (!f) return false;
  const ageDays = (nowMs - new Date(f.verified_at).getTime()) / 86400000;
  return ageDays > STALE_AFTER_DAYS;
}

const CANONICAL_TARGETS = [
  { field: 'legal_name', factType: 'legal_name' },
  { field: 'hq_location', factType: 'headquarters' },
  { field: 'employee_count', factType: 'employee_count' },
  { field: 'revenue', factType: 'revenue' },
  { field: 'website', factType: 'website' },
  { field: 'description', factType: 'primary_activity' },
];

const researchTargets = [];
for (const t of CANONICAL_TARGETS) {
  const value = canonical[t.field];
  const missing = value === null || value === undefined || value === '';
  if (missing) researchTargets.push({ field: t.field, reason: 'missing' });
  else if (isStale(t.factType)) researchTargets.push({ field: t.field, reason: 'stale' });
}

const siteUrl = canonical.website && /^https?:\/\//i.test(canonical.website) ? canonical.website : null;
const needsResearch = researchTargets.length > 0;

return [{
  json: {
    ...upstream,
    canonical,
    verifiedFacts,
    factSources,
    factSourceLinks,
    relational,
    processDiagnostic: ctx.processDiagnostic || null,
    folioLegacy,
    hasFolio,
    researchTargets,
    needsResearch,
    // Sentinelle documentée : le nœud de fetch du site officiel s'exécute sur la
    // branche "recherche nécessaire" même sans site connu. Une URL invalide y est
    // volontairement passée (le nœud est en continueRegularOutput) et la réponse
    // est écartée en aval — plus lisible qu'un second IF pour ce seul cas.
    siteUrl: siteUrl || 'https://kredo.invalid/no-official-site',
    hasSiteUrl: !!siteUrl,
    dataCutoffAt: ctx.dataCutoffAt || new Date().toISOString(),
  }
}];

// Constitution des PREUVES externes. Règle absolue : seule une page réellement
// récupérée fait preuve. Aucun moteur de recherche n'est interrogé, aucun
// snippet n'est utilisé — uniquement le site officiel du compte (HTML réel) et
// l'API publique Recherche d'entreprises (data.gouv.fr / INSEE Sirene).
const ctx = $('Prepare Deterministic Context').first().json;
const siteResponse = $('Fetch Official Site').first().json || {};
const registryResponse = $input.first().json || {};

function simpleHash(str) {
  let h = 5381;
  const s = String(str == null ? '' : str);
  for (let i = 0; i < s.length; i += 1) h = ((h << 5) + h + s.charCodeAt(i)) | 0;
  return (h >>> 0).toString(16);
}

function canonicalUrl(url) {
  try {
    const u = new URL(url);
    u.search = '';
    u.hash = '';
    return u.toString();
  } catch (e) {
    return url;
  }
}

function htmlToText(html) {
  return String(html || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeName(v) {
  return String(v || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

const nowIso = new Date().toISOString();
const evidence = [];
const warnings = [];

// ── Site officiel ──────────────────────────────────────────────────────────
const siteStatus = Number(siteResponse.statusCode || 0);
const siteBody = typeof siteResponse.body === 'string' ? siteResponse.body : '';
if (!ctx.hasSiteUrl) {
  warnings.push("Aucun site officiel connu sur la fiche compte — recherche limitée au registre public.");
} else if (siteStatus < 200 || siteStatus >= 300 || siteBody.length === 0) {
  warnings.push(`Site officiel injoignable (statut ${siteStatus || 'inconnu'}) — aucune preuve retenue.`);
} else {
  const text = htmlToText(siteBody).slice(0, 12000);
  if (text.length < 120) {
    warnings.push('Site officiel récupéré mais sans texte exploitable (rendu JS probable).');
  } else {
    evidence.push({
      kind: 'official_site',
      sourceKey: `account_knowledge:site:${simpleHash(canonicalUrl(ctx.siteUrl))}`,
      sourceType: 'official_site',
      sourceName: `${ctx.canonical.name} — site officiel`,
      url: ctx.siteUrl,
      canonicalUrl: canonicalUrl(ctx.siteUrl),
      publishedAt: null,
      reliability: 0.75,
      collectionMethod: 'scrape',
      excerpt: text.slice(0, 500),
      text,
      covers: "Discours officiel du compte : activité revendiquée, offre, implantations, clients cités.",
    });
  }
}

// ── Registre public (INSEE Sirene via data.gouv.fr) ─────────────────────────
const registryStatus = Number(registryResponse.statusCode || 0);
const registryBody = registryResponse.body || {};
const results = Array.isArray(registryBody.results) ? registryBody.results : [];
if (registryStatus < 200 || registryStatus >= 300) {
  warnings.push(`Registre public injoignable (statut ${registryStatus || 'inconnu'}).`);
} else if (results.length === 0) {
  warnings.push('Aucune entité juridique trouvée au registre public pour ce nom.');
} else {
  const target = normalizeName(ctx.canonical.legal_name || ctx.canonical.name);
  const scored = results.map((r) => {
    const candidate = normalizeName(r.nom_raison_sociale || r.nom_complet);
    let score = 0;
    if (candidate === target) score = 1;
    else if (candidate.startsWith(target) || target.startsWith(candidate)) score = 0.8;
    else if (candidate.includes(target) || target.includes(candidate)) score = 0.6;
    return { r, score };
  }).sort((a, b) => b.score - a.score);

  const best = scored[0];
  // Sous 0.6, la correspondance n'est pas assez nette : on ne rattache rien
  // plutôt que de sourcer le compte sur une homonymie.
  if (!best || best.score < 0.6) {
    warnings.push("Correspondance au registre public trop incertaine — aucune donnée légale retenue.");
  } else {
    const r = best.r;
    const siege = r.siege || {};
    const tranche = String(r.tranche_effectif_salarie || siege.tranche_effectif_salarie || '');
    const TRANCHES = {
      '00': 0, '01': 2, '02': 4, '03': 7, '11': 15, '12': 35, '21': 75,
      '22': 150, '31': 225, '32': 375, '41': 750, '42': 1500, '51': 3500, '52': 7500,
    };
    evidence.push({
      kind: 'registry',
      sourceKey: `account_knowledge:registry:${r.siren}`,
      sourceType: 'regulatory_filing',
      sourceName: "Recherche d'entreprises (data.gouv.fr / INSEE Sirene)",
      url: `https://recherche-entreprises.api.gouv.fr/search?q=${r.siren}`,
      canonicalUrl: `https://annuaire-entreprises.data.gouv.fr/entreprise/${r.siren}`,
      publishedAt: r.date_mise_a_jour || null,
      reliability: 0.97,
      collectionMethod: 'api',
      excerpt: `SIREN ${r.siren} — ${r.nom_raison_sociale || r.nom_complet}`.slice(0, 500),
      covers: "Identité juridique officielle : raison sociale, SIREN, code NAF, siège, tranche d'effectif.",
      registry: {
        siren: r.siren || null,
        legalName: r.nom_raison_sociale || r.nom_complet || null,
        nafCode: r.activite_principale || null,
        activityLabel: r.libelle_activite_principale || null,
        hqLocation: [siege.libelle_commune, siege.code_postal].filter(Boolean).join(' ') || null,
        employeeCount: Object.prototype.hasOwnProperty.call(TRANCHES, tranche) ? TRANCHES[tranche] : null,
        employeeCountIsEstimate: true,
        matchScore: best.score,
      },
      text: JSON.stringify({
        siren: r.siren,
        raison_sociale: r.nom_raison_sociale || r.nom_complet,
        activite_principale: r.activite_principale,
        libelle_activite_principale: r.libelle_activite_principale,
        siege: { commune: siege.libelle_commune, code_postal: siege.code_postal },
        tranche_effectif_salarie: tranche,
      }),
    });
  }
}

return [{ json: { externalEvidence: evidence, researchWarnings: warnings, researchPerformed: true } }];

// Aucune donnée canonique manquante ni périmée : aucune requête externe.
// Un item est renvoyé malgré tout — un nœud Code qui renvoie [] n'émet aucun
// item, et n8n n'exécute pas le nœud suivant : la chaîne s'arrêterait ici en
// silence, run bloqué en "running" (piège déjà rencontré sur intel-010/033).
return [{ json: { externalEvidence: [], researchWarnings: [], researchPerformed: false } }];

// Point de convergence STABLE des deux branches de recherche : ce nœud relit le
// contexte depuis "Prepare Deterministic Context" (toujours exécuté) et ne
// référence jamais une branche IF qui pourrait ne pas s'être exécutée.
const ctx = $('Prepare Deterministic Context').first().json;
const research = $input.first().json || {};
const evidence = research.externalEvidence || [];

const nowIso = new Date().toISOString();

// Source interne « base relationnelle KREDO ». Ce n'est PAS une source inventée :
// c'est une origine réelle, identifiable et datée, prévue par le schéma
// (source_type 'internal_crm'). Sans elle, aucun fait tiré du CRM ne pourrait
// être cité — or le contrat V2 exige une source pour toute affirmation.
const crmSource = {
  workspace_id: ctx.workspaceId,
  source_type: 'internal_crm',
  source_name: `Base relationnelle KREDO — ${ctx.canonical.name}`,
  source_url: null,
  canonical_url: null,
  published_at: null,
  collected_at: nowIso,
  source_key: `account_knowledge:crm:${ctx.companyId}`,
  evidence_excerpt: `Contacts: ${ctx.relational.contacts.length} · interactions: ${ctx.relational.recentInteractions.length} · opportunités: ${ctx.relational.opportunities.length} · missions: ${ctx.relational.missions.length} · signaux: ${ctx.relational.signals.length}`.slice(0, 500),
  reliability_score: 0.9,
  collection_method: 'system_sync',
  technical_metadata: { collector: 'intel-030-account-knowledge', runId: ctx.runId },
};

const sourcesPayload = [crmSource];
for (const e of evidence) {
  sourcesPayload.push({
    workspace_id: ctx.workspaceId,
    source_type: e.sourceType,
    source_name: e.sourceName,
    source_url: e.url,
    canonical_url: e.canonicalUrl,
    published_at: e.publishedAt,
    collected_at: nowIso,
    source_key: e.sourceKey,
    evidence_excerpt: e.excerpt,
    reliability_score: e.reliability,
    collection_method: e.collectionMethod,
    technical_metadata: { collector: 'intel-030-account-knowledge', runId: ctx.runId, kind: e.kind },
  });
}

// Déduplication sur source_key AVANT l'appel : l'upsert est idempotent côté
// base (index unique workspace_id+source_key), mais un même lot porteur de deux
// fois la même clé serait rejeté par PostgREST.
const bySourceKey = new Map();
for (const s of sourcesPayload) {
  if (!bySourceKey.has(s.source_key)) bySourceKey.set(s.source_key, s);
}
const deduped = Array.from(bySourceKey.values());

return [{
  json: {
    ...ctx,
    externalEvidence: evidence,
    researchWarnings: research.researchWarnings || [],
    researchPerformed: !!research.researchPerformed,
    sourcesPayload: deduped,
    sourceKeys: Array.from(bySourceKey.keys()),
  }
}];

const ctx = $('Build Source Catalogue').first().json;
const resolved = $input.all().map((i) => i.json).filter((r) => r && r.id && r.source_key);
const idBySourceKey = new Map(resolved.map((r) => [r.source_key, r.id]));

if (idBySourceKey.size === 0) {
  throw new Error('Aucune source résolue : impossible de produire un artefact sourcé');
}

const crmSourceId = idBySourceKey.get(`account_knowledge:crm:${ctx.companyId}`) || null;
if (!crmSourceId) {
  throw new Error('Source interne (base relationnelle KREDO) non résolue');
}

// ── Catalogue des sources citables ─────────────────────────────────────────
// Le modèle ne peut citer QUE ces identifiants. Toute autre valeur est rejetée
// par "Parse & Validate Output", puis à nouveau par le callback applicatif.
const catalogue = [];

catalogue.push({
  source_id: crmSourceId,
  type: 'internal_crm',
  name: 'Base relationnelle KREDO',
  covers: "Contacts, interactions, opportunités, missions et signaux du compte tels qu'enregistrés dans KREDO.",
});

for (const e of ctx.externalEvidence) {
  const id = idBySourceKey.get(e.sourceKey);
  if (!id) continue;
  catalogue.push({
    source_id: id,
    type: e.sourceType,
    name: e.sourceName,
    url: e.canonicalUrl || e.url,
    published_at: e.publishedAt,
    covers: e.covers,
    content: e.text ? String(e.text).slice(0, 9000) : null,
  });
}

// Sources déjà rattachées aux faits vérifiés du compte (Lot 0) : citables aussi,
// puisqu'elles existent réellement en base et appartiennent au workspace.
const linksByFact = new Map();
for (const l of (ctx.factSourceLinks || [])) {
  if (!linksByFact.has(l.fact_id)) linksByFact.set(l.fact_id, []);
  linksByFact.get(l.fact_id).push(l.source_id);
}
for (const s of (ctx.factSources || [])) {
  if (catalogue.some((c) => c.source_id === s.id)) continue;
  catalogue.push({
    source_id: s.id,
    type: s.source_type,
    name: s.source_name,
    url: s.canonical_url || s.source_url,
    published_at: s.published_at,
    covers: 'Source déjà rattachée à un fait vérifié du compte.',
    excerpt: s.evidence_excerpt || null,
  });
}

const verifiedFacts = (ctx.verifiedFacts || []).map((f) => ({
  fact_type: f.fact_type,
  fact_subtype: f.fact_subtype,
  value: f.value_text || f.normalized_value || f.value_json,
  verified_at: f.verified_at,
  source_refs: [f.primary_source_id, ...(linksByFact.get(f.id) || [])].filter(Boolean),
}));

const SYSTEM_PROMPT = `Tu rédiges la "Connaissance entreprise" d'un compte pour Kredo Digital (ESN premium).
Tu produis un artefact machine, en JSON strict, au schéma account_knowledge V2.

RÈGLE FONDATRICE — TOUTE AFFIRMATION EST SOURCÉE.
Chaque objet "Claim" que tu produis a la forme :
  { "text": "...", "nature": "fact"|"analysis", "source_refs": ["<uuid>"], "confidence": 0.0-1.0, "verified_at": null }
- "source_refs" ne peut contenir QUE des identifiants présents dans SOURCE_CATALOGUE ci-dessous.
  N'invente JAMAIS d'identifiant. Un Claim sans source valide est refusé et fait échouer la génération.
- "fact" = énoncé vérifiable dans une source citée.
- "analysis" = déduction ; elle DOIT citer les sources des faits sur lesquels elle s'appuie.
- "confidence" reflète ta certitude, strictement entre 0 et 1.
- "verified_at" vaut toujours null (la vérification est un geste humain, pas le tien).

INTERDICTIONS ABSOLUES :
1. Ne jamais écrire "Non trouvé", "N/A", "Non renseigné", "-" ni aucun marqueur d'absence.
   Une section sans matière solide reste VIDE (tableau vide, ou null pour un champ unique).
2. FOLIO_LEGACY (bloc plus bas) est une donnée d'import ANCIENNE et NON SOURCÉE.
   Elle peut t'indiquer quoi chercher dans les sources réelles ; elle ne peut JAMAIS devenir un Claim
   à elle seule. Si une information n'existe QUE dans FOLIO_LEGACY, ne la produis pas.
3. Aucune donnée sectorielle macro (taille de marché, croissance du secteur, réglementation
   sectorielle, concurrence générale du secteur) : c'est une autre étape de la chaîne.
   Les concurrents cités doivent être ceux du compte, attestés par une source.
4. Aucune recommandation commerciale, aucun plan d'action, aucune roadmap, aucune offre suggérée.
5. Volume borné : au plus 6 entrées par tableau de Claims, et 40 Claims au total sur
   l'ensemble de l'artefact. Mieux vaut 3 affirmations solidement sourcées que 12 diluées.
   (Contrainte technique autant qu'éditoriale : une réponse trop longue est tronquée et
   rendue inexploitable.)
6. "identity.dynamic" vaut TOUJOURS null : cet indicateur est calculé de façon déterministe
   par l'application, hors modèle. Toute autre valeur fait échouer la génération.

FORMAT DE SORTIE — JSON valide UNIQUEMENT, sans backticks, structure EXACTE :
{
  "schema_version": 2,
  "identity": {
    "primary_activity": Claim|null,
    "headquarters": Claim|null,
    "revenue": Claim|null,
    "employee_count": Claim|null,
    "dynamic": null
  },
  "account_summary": Claim|null,
  "market_positioning": {
    "positioning": Claim|null,
    "direct_competitors": [Claim],
    "customer_segments": [Claim],
    "differentiators": [Claim],
    "uncovered_scope": [Claim],
    "claimed_identity": Claim|null,
    "threats": [Claim],
    "opportunities": [Claim]
  },
  "company_value_chain": {
    "description": Claim|null,
    "value_proposition": Claim|null,
    "key_links": [Claim],
    "dependencies": [Claim],
    "vulnerabilities": [Claim],
    "customer_base": [Claim]
  },
  "organisation": {
    "departments": [Claim],
    "strategic_weight": Claim|null,
    "key_contacts": [ { "contact_id": "<uuid d'un contact fourni>", "role_summary": Claim } ],
    "process_observations": [Claim]
  },
  "open_questions": [ { "question": "...", "why_it_matters": "..." } ],
  "generated_at": "<ISO8601>"
}

"open_questions" n'est PAS un Claim : on y pose ce qu'on ignore, on n'y affirme rien — donc pas de source.
"organisation.key_contacts[].contact_id" doit être l'identifiant exact d'un contact de CONTEXT.relational.contacts.
Style direct, factuel, sans superlatif.`;

const userPayload = {
  SOURCE_CATALOGUE: catalogue,
  CANONICAL: ctx.canonical,
  VERIFIED_FACTS: verifiedFacts,
  RELATIONAL: ctx.relational,
  PROCESS_DIAGNOSTIC: ctx.processDiagnostic,
  FOLIO_LEGACY_NON_SOURCE: ctx.folioLegacy,
  RESEARCH_TARGETS: ctx.researchTargets,
  DATA_CUTOFF_AT: ctx.dataCutoffAt,
};

return [{
  json: {
    ...ctx,
    catalogue,
    allowedSourceIds: catalogue.map((c) => c.source_id),
    crmSourceId,
    sourceIdByKey: Array.from(idBySourceKey.entries()).map(([source_key, id]) => ({ source_key, id })),
    systemPrompt: SYSTEM_PROMPT,
    userPrompt: `CONTEXTE (source unique de vérité — JSON) :\n${JSON.stringify(userPayload, null, 2)}`,
  }
}];

// Validation STRICTE avant toute écriture. Ce nœud est le miroir JS de
// validateAccountKnowledgeV2 (src/lib/intelligence/intelligence-validators.ts) :
// le callback applicatif refera la même vérification côté Next — la double
// barrière est volontaire (n8n tourne en service_role, il ne se valide pas seul).
const response = $input.first().json;
const upstream = $('Assemble Prompt').first().json;

const textBlock = (response.content || []).find((b) => b.type === 'text');
const content = textBlock && textBlock.text;
if (!content) throw new Error('Le LLM a renvoyé un contenu vide');

// Une réponse tronquée (plafond de tokens atteint) produit un JSON incomplet.
// Sans ce contrôle, l'échec se présente comme « réponse non-JSON » et l'extrait
// affiché commence par la clôture de bloc Markdown — diagnostic trompeur.
if (response.stop_reason === 'max_tokens') {
  throw new Error(
    'Réponse LLM tronquée (plafond de tokens atteint) : artefact incomplet, non exploitable. '
    + 'Réduire le volume attendu ou augmenter max_tokens sur le nœud Call LLM.'
  );
}

// Nettoyage tolérant : bloc Markdown avec ou sans langage, avec \r\n, et
// éventuel texte d'introduction avant l'objet JSON.
function extractJsonPayload(raw) {
  let text = String(raw).trim();
  const fenced = text.match(/```[a-zA-Z]*\s*([\s\S]*?)```/);
  if (fenced) text = fenced[1].trim();
  else text = text.replace(/```[a-zA-Z]*\s*/g, '').replace(/```/g, '').trim();
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start > 0 || (end !== -1 && end < text.length - 1)) {
    if (start !== -1 && end > start) text = text.slice(start, end + 1);
  }
  return text;
}

let parsed;
const payload = extractJsonPayload(content);
try {
  parsed = JSON.parse(payload);
} catch (e) {
  throw new Error(
    `Réponse LLM non-JSON (${e.message}) — début: ${payload.slice(0, 160)} | fin: ${payload.slice(-160)}`
  );
}

if (parsed.schema_version !== 2) throw new Error('schema_version doit valoir 2');

const allowed = new Set(upstream.allowedSourceIds || []);
const contactIds = new Set((upstream.relational.contacts || []).map((c) => c.id));
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

const PLACEHOLDERS = new Set(['non trouve', 'non renseigne', 'non communique', 'non disponible', 'inconnu', 'n/a', 'na', 'nc', '-', '--']);
function isPlaceholder(text) {
  const n = String(text || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/\s+/g, ' ').trim();
  return n.length === 0 || PLACEHOLDERS.has(n);
}

const errors = [];
const claims = [];

function checkClaim(value, path) {
  if (value === null || value === undefined) {
    errors.push(`${path} : Claim ou null explicite attendu`);
    return;
  }
  if (typeof value !== 'object' || Array.isArray(value)) {
    errors.push(`${path} : objet Claim attendu`);
    return;
  }
  if (typeof value.text !== 'string' || value.text.trim().length === 0) errors.push(`${path}.text : texte requis`);
  else if (isPlaceholder(value.text)) errors.push(`${path}.text : marqueur d'absence interdit ("${value.text.trim()}")`);

  if (value.nature !== 'fact' && value.nature !== 'analysis') errors.push(`${path}.nature : "fact" ou "analysis" attendu`);

  if (!Array.isArray(value.source_refs) || value.source_refs.length === 0) {
    errors.push(`${path}.source_refs : au moins une source requise (aucune affirmation non sourcée)`);
  } else {
    value.source_refs.forEach((ref, i) => {
      if (!UUID.test(String(ref))) errors.push(`${path}.source_refs[${i}] : UUID invalide`);
      else if (!allowed.has(ref)) errors.push(`${path}.source_refs[${i}] : source hors catalogue (${ref})`);
    });
  }

  if (typeof value.confidence !== 'number' || !isFinite(value.confidence)) errors.push(`${path}.confidence : nombre requis`);
  else if (value.confidence < 0 || value.confidence > 1) errors.push(`${path}.confidence : hors bornes [0,1]`);

  if (value.verified_at !== null && value.verified_at !== undefined) {
    errors.push(`${path}.verified_at : doit rester null (vérification humaine)`);
  }
  value.verified_at = null;

  claims.push({ path, sourced: Array.isArray(value.source_refs) && value.source_refs.length > 0, refs: value.source_refs || [] });
}

function checkNullableClaim(value, path) {
  if (value === null) return;
  if (value === undefined) { errors.push(`${path} : champ requis (Claim ou null)`); return; }
  checkClaim(value, path);
}

function checkClaimArray(value, path) {
  if (!Array.isArray(value)) { errors.push(`${path} : tableau requis`); return; }
  value.forEach((c, i) => checkClaim(c, `${path}[${i}]`));
}

function section(obj, path) {
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) {
    errors.push(`${path} : section obligatoire absente`);
    return null;
  }
  return obj;
}

// identity
const identity = section(parsed.identity, 'identity');
if (identity) {
  ['primary_activity', 'headquarters', 'revenue', 'employee_count'].forEach((k) => checkNullableClaim(identity[k], `identity.${k}`));
  // Indicateur déterministe : le modèle n'a pas le droit de le produire.
  if (identity.dynamic !== null && identity.dynamic !== undefined) {
    errors.push('identity.dynamic : doit valoir null (indicateur calculé hors modèle)');
  }
  identity.dynamic = null;
}

checkNullableClaim(parsed.account_summary, 'account_summary');

const mp = section(parsed.market_positioning, 'market_positioning');
if (mp) {
  checkNullableClaim(mp.positioning, 'market_positioning.positioning');
  checkNullableClaim(mp.claimed_identity, 'market_positioning.claimed_identity');
  ['direct_competitors', 'customer_segments', 'differentiators', 'uncovered_scope', 'threats', 'opportunities']
    .forEach((k) => checkClaimArray(mp[k], `market_positioning.${k}`));
}

const vc = section(parsed.company_value_chain, 'company_value_chain');
if (vc) {
  checkNullableClaim(vc.description, 'company_value_chain.description');
  checkNullableClaim(vc.value_proposition, 'company_value_chain.value_proposition');
  ['key_links', 'dependencies', 'vulnerabilities', 'customer_base']
    .forEach((k) => checkClaimArray(vc[k], `company_value_chain.${k}`));
}

const org = section(parsed.organisation, 'organisation');
if (org) {
  checkClaimArray(org.departments, 'organisation.departments');
  checkClaimArray(org.process_observations, 'organisation.process_observations');
  checkNullableClaim(org.strategic_weight, 'organisation.strategic_weight');
  if (!Array.isArray(org.key_contacts)) errors.push('organisation.key_contacts : tableau requis');
  else org.key_contacts.forEach((kc, i) => {
    const p = `organisation.key_contacts[${i}]`;
    if (!kc || typeof kc !== 'object') { errors.push(`${p} : objet attendu`); return; }
    if (!UUID.test(String(kc.contact_id))) errors.push(`${p}.contact_id : UUID invalide`);
    else if (!contactIds.has(kc.contact_id)) errors.push(`${p}.contact_id : contact inconnu du compte`);
    checkClaim(kc.role_summary, `${p}.role_summary`);
  });
}

if (!Array.isArray(parsed.open_questions)) errors.push('open_questions : tableau requis');
else parsed.open_questions.forEach((q, i) => {
  if (!q || typeof q !== 'object' || typeof q.question !== 'string' || q.question.trim().length === 0) {
    errors.push(`open_questions[${i}].question : question requise`);
  } else if (isPlaceholder(q.question)) {
    errors.push(`open_questions[${i}].question : marqueur d'absence interdit`);
  }
});

if (errors.length > 0) {
  throw new Error(`Artefact account_knowledge V2 invalide (${errors.length}) : ` + errors.slice(0, 12).join(' | '));
}

// ── Couverture de sourcing, calculée (jamais rédigée par le modèle) ─────────
const displayed = claims.length;
const sourced = claims.filter((c) => c.sourced).length;
const sourceCoverage = {
  displayed_claims: displayed,
  sourced_claims: sourced,
  coverage_rate: displayed === 0 ? 1 : sourced / displayed,
  missing_source_paths: claims.filter((c) => !c.sourced).map((c) => c.path),
  stale_source_paths: [],
  contradiction_paths: [],
  passed: sourced === displayed,
};

const accountKnowledge = {
  schema_version: 2,
  identity: parsed.identity,
  account_summary: parsed.account_summary === undefined ? null : parsed.account_summary,
  market_positioning: parsed.market_positioning,
  company_value_chain: parsed.company_value_chain,
  organisation: parsed.organisation,
  open_questions: parsed.open_questions,
  source_coverage: sourceCoverage,
  generated_at: new Date().toISOString(),
};

const usedSourceIds = Array.from(new Set(claims.flatMap((c) => c.refs)));

return [{
  json: {
    ...upstream,
    accountKnowledge,
    usedSourceIds,
    llmUsage: {
      inputTokens: (response.usage && response.usage.input_tokens) || null,
      outputTokens: (response.usage && response.usage.output_tokens) || null,
      model: response.model || 'claude-sonnet-5',
    },
  }
}];

// Contrôles qualité exposés dans qa_flags. Les manquements bloquants ont déjà
// fait échouer "Parse & Validate Output" : ce qui reste ici est informatif.
const data = $input.first().json;
const ak = data.accountKnowledge;
const cov = ak.source_coverage;
const qaFlags = [];

qaFlags.push({ check: 'all_claims_sourced', passed: cov.passed, detail: `${cov.sourced_claims}/${cov.displayed_claims} affirmations sourcées` });
qaFlags.push({ check: 'dynamic_left_to_engine', passed: ak.identity.dynamic === null, detail: 'indicateur de dynamique calculé hors modèle' });
qaFlags.push({ check: 'external_research_performed', passed: !!data.researchPerformed, detail: data.researchPerformed ? `${(data.externalEvidence || []).length} preuve(s) externe(s) collectée(s)` : 'aucune donnée canonique manquante ou périmée' });

// Aucune source de type folio_legacy ne doit apparaître au catalogue : FOLIO n'a
// aucune origine vérifiable, en fabriquer une serait un faux sourcing.
const folioSources = (data.catalogue || []).filter((c) => c.type === 'folio_legacy');
qaFlags.push({ check: 'no_folio_source', passed: folioSources.length === 0, detail: folioSources.length === 0 ? 'OK' : `${folioSources.length} source folio_legacy au catalogue` });

const emptySections = [];
if ((ak.market_positioning.direct_competitors || []).length === 0) emptySections.push('market_positioning.direct_competitors');
if ((ak.organisation.departments || []).length === 0) emptySections.push('organisation.departments');
if ((ak.company_value_chain.key_links || []).length === 0) emptySections.push('company_value_chain.key_links');
qaFlags.push({ check: 'sections_populated', passed: emptySections.length === 0, detail: emptySections.length === 0 ? 'OK' : `vides (honnêtement, faute de source) : ${emptySections.join(', ')}` });

const hasContacts = (data.relational.contacts || []).length > 0;
qaFlags.push({
  check: 'key_contacts_present_if_contacts_exist',
  passed: !hasContacts || (ak.organisation.key_contacts || []).length > 0,
  detail: hasContacts ? `${(ak.organisation.key_contacts || []).length} synthèses pour ${data.relational.contacts.length} contacts` : 'aucun contact en base',
});

for (const w of (data.researchWarnings || [])) {
  qaFlags.push({ check: 'research_warning', passed: true, detail: w });
}

return [{ json: { ...data, qaFlags } }];

// Propositions d'enrichissement — SEUL chemin d'écriture vers les données
// canoniques du compte. Ce workflow n'écrit JAMAIS dans `companies` : une
// donnée canonique ne change qu'après validation humaine
// (validate_and_apply_enrichment_proposals).
//
// L'espace de nommage `account_scan:{companyId}:{attribut}` est VOLONTAIREMENT
// partagé avec intel-010-refresh : la clé identifie l'attribut du compte, pas le
// workflow producteur. Deux préfixes distincts créeraient deux propositions
// concurrentes pour le même champ, toutes deux "actives" (l'index unique porte
// sur workspace_id + proposal_key). Ici, le plus récent remplace le précédent
// tant qu'aucune décision humaine n'a été prise.
const data = $('Quality Check').first().json;
const activeProposals = $input.all().map((i) => i.json).filter((r) => r && r.proposal_key);
const sourceIdByKey = new Map((data.sourceIdByKey || []).map((r) => [r.source_key, r.id]));

function simpleHash(str) {
  let h = 5381;
  const s = String(str == null ? '' : str);
  for (let i = 0; i < s.length; i += 1) h = ((h << 5) + h + s.charCodeAt(i)) | 0;
  return (h >>> 0).toString(16);
}

function norm(v) {
  if (v === null || v === undefined) return null;
  const t = String(v).replace(/\s+/g, ' ').trim();
  return t.length > 0 ? t.toLowerCase() : null;
}

const registryEvidence = (data.externalEvidence || []).find((e) => e.kind === 'registry');
const siteEvidence = (data.externalEvidence || []).find((e) => e.kind === 'official_site');
const canonical = data.canonical;
const candidates = [];
const warnings = [];

function propose({ attribute, value, sourceKey, confidence, justification, currentValue }) {
  const proposed = norm(value);
  if (!proposed) return;
  // Ne créer une proposition QUE si la valeur diffère réellement de l'actuelle.
  if (norm(currentValue) === proposed) return;
  candidates.push({
    proposal_key: `account_scan:${data.companyId}:${attribute}`,
    target_type: 'company',
    target_id: data.companyId,
    attribute_name: attribute,
    proposed_value: String(value).trim(),
    normalized_value: proposed,
    normalized_value_hash: simpleHash(proposed),
    initial_snapshot: { current: currentValue === undefined ? null : currentValue },
    primary_source_id: sourceIdByKey.get(sourceKey) || null,
    origin: 'external',
    confidence_score: confidence,
    justification,
    status: confidence < 0.45 ? 'needs_review' : 'proposed',
    run_id: data.runId,
    workspace_id: data.workspaceId,
  });
}

if (registryEvidence && registryEvidence.registry) {
  const r = registryEvidence.registry;
  const key = registryEvidence.sourceKey;
  propose({ attribute: 'legal_name', value: r.legalName, sourceKey: key, confidence: 0.95,
    justification: `Raison sociale au registre public (SIREN ${r.siren}).`, currentValue: canonical.legal_name });
  propose({ attribute: 'siren', value: r.siren, sourceKey: key, confidence: 0.95,
    justification: 'SIREN issu du registre public.', currentValue: null });
  propose({ attribute: 'naf_code', value: r.nafCode, sourceKey: key, confidence: 0.9,
    justification: `Code NAF déclaré : ${r.activityLabel || r.nafCode}.`, currentValue: null });
  propose({ attribute: 'hq_location', value: r.hqLocation, sourceKey: key, confidence: 0.85,
    justification: 'Commune du siège au registre public.', currentValue: canonical.hq_location });
  if (r.employeeCount !== null) {
    // Tranche INSEE ramenée à son point médian : une ESTIMATION, jamais
    // présentée avec la même certitude qu'une valeur exacte.
    propose({ attribute: 'employee_count', value: r.employeeCount, sourceKey: key, confidence: 0.55,
      justification: "Estimation issue de la tranche d'effectif INSEE (point médian de la tranche).",
      currentValue: canonical.employee_count });
  }
  if (r.activityLabel) {
    propose({ attribute: 'description', value: r.activityLabel, sourceKey: key, confidence: 0.6,
      justification: "Libellé de l'activité principale déclarée au registre public.",
      currentValue: canonical.description });
  }
} else {
  warnings.push('Aucune entité juridique résolue : aucune proposition sur les données canoniques légales.');
}

if (siteEvidence && !canonical.website) {
  propose({ attribute: 'website', value: siteEvidence.canonicalUrl || siteEvidence.url, sourceKey: siteEvidence.sourceKey,
    confidence: 0.7, justification: 'Site officiel effectivement récupéré.', currentValue: canonical.website });
}

// ── Réconciliation idempotente ─────────────────────────────────────────────
const byKey = new Map(activeProposals.map((p) => [p.proposal_key, p]));
// Une proposition 'validated' ou 'conflicting' porte une décision humaine ou un
// conflit non résolu : jamais régénérée en silence.
const untouched = new Set(activeProposals.filter((p) => ['validated', 'conflicting'].includes(p.status)).map((p) => p.proposal_key));

const toInsert = [];
const staleIdsToDelete = [];
for (const c of candidates) {
  if (untouched.has(c.proposal_key)) {
    warnings.push(`Proposition déjà décidée ou en conflit pour "${c.attribute_name}" — non régénérée.`);
    continue;
  }
  const existing = byKey.get(c.proposal_key);
  if (existing && ['proposed', 'needs_review'].includes(existing.status)) {
    // Même valeur qu'une proposition déjà en attente : rien à réécrire.
    if (norm(existing.proposed_value) === c.normalized_value) continue;
    staleIdsToDelete.push(existing.id);
  }
  toInsert.push(c);
}

return [{
  json: {
    ...data,
    proposalWarnings: warnings,
    toInsert,
    staleIdsToDelete,
    proposalsCount: toInsert.length,
  }
}];

// Aucune proposition à écrire. Un item est renvoyé quand même : sans lui, le
// nœud suivant ne serait pas exécuté et le run resterait bloqué en "running".
return [{ json: { proposalsInserted: 0 } }];

// Point de convergence stable : relit tout depuis "Build Enrichment Proposals",
// jamais depuis une branche IF qui a pu ne pas s'exécuter.
const data = $('Build Enrichment Proposals').first().json;
const companyName = (data.canonical && data.canonical.name) || 'Compte';

// Union des sources : celles réellement citées par les Claims, plus celles
// mobilisées par l'indicateur déterministe côté applicatif (résolues là-bas).
const sourceRefs = Array.from(new Set(data.usedSourceIds || [])).map((id) => ({
  entityType: 'intelligence_source',
  entityId: id,
  label: (data.catalogue || []).find((c) => c.source_id === id)?.name || 'Source',
}));

const qaFlags = [
  ...(data.qaFlags || []),
  ...(data.proposalWarnings || []).map((w) => ({ check: 'proposal_warning', passed: true, detail: w })),
  { check: 'enrichment_proposals_written', passed: true, detail: `${data.proposalsCount} proposition(s) d'enrichissement` },
];

const startedAt = $('Validate Entity').first().json.startedAtMs || null;

const callbackBody = {
  n8nExecutionId: $execution.id,
  n8nWorkflowId: $workflow.id,
  runId: data.runId,
  phase: 1,
  resultType: 'account_knowledge',
  status: 'succeeded',
  contentJson: data.accountKnowledge,
  contentText: [
    `# Connaissance entreprise — ${companyName}`,
    data.accountKnowledge.account_summary ? data.accountKnowledge.account_summary.text : '',
  ].filter(Boolean).join('\n\n'),
  title: `Connaissance entreprise — ${companyName}`,
  modelProvider: 'anthropic',
  modelUsed: (data.llmUsage && data.llmUsage.model) || 'claude-sonnet-5',
  tokensInput: (data.llmUsage && data.llmUsage.inputTokens) || null,
  tokensOutput: (data.llmUsage && data.llmUsage.outputTokens) || null,
  durationMs: startedAt ? (Date.now() - startedAt) : null,
  contextSnapshot: {
    canonical: data.canonical,
    researchTargets: data.researchTargets,
    researchPerformed: data.researchPerformed,
    catalogue: (data.catalogue || []).map(({ content, ...rest }) => rest),
    dataCutoffAt: data.dataCutoffAt,
  },
  sourceRefs,
  qaFlags,
};

return [{ json: { callbackUrl: data.callbackUrl, rawBody: JSON.stringify(callbackBody) } }];

// Chemin d'échec : quelle que soit l'étape fautive, le run doit être notifié en
// "failed". Un run laissé en "running" ne serait repris que par le reaper
// (ops-004), 30 minutes plus tard — l'utilisateur resterait devant un écran
// « en cours » sans issue.
const errItem = $input.first().json;
let runId = null;
let callbackUrl = null;

try {
  const ve = $('Validate Entity').first().json;
  runId = ve.runId || null;
  callbackUrl = ve.callbackUrl || null;
} catch (e) {
  // Validate Entity n'a produit aucune sortie exploitable — notification impossible.
}

if (!callbackUrl || !runId) {
  // Sans URL de callback, KREDO ne peut pas être notifié : on lève une erreur
  // visible dans l'exécution n8n plutôt que d'appeler une URL nulle (le nœud
  // HTTP échouait alors sur « URL parameter must be a string, got null »,
  // masquant la vraie cause). Le reaper ops-004 reprendra le run.
  throw new Error(
    'Échec non notifiable : runId ou callbackUrl introuvable en amont — '
    + 'le run sera repris par reap_stale_intelligence_runs.'
  );
}

let errorMessage = 'Erreur inconnue dans le workflow intel-030-account-knowledge';
if (errItem && errItem.error) {
  errorMessage = typeof errItem.error === 'string' ? errItem.error : (errItem.error.message || JSON.stringify(errItem.error));
} else if (errItem && errItem.message) {
  errorMessage = errItem.message;
}

const callbackBody = {
  n8nExecutionId: $execution.id,
  n8nWorkflowId: $workflow.id,
  runId,
  phase: 1,
  resultType: 'account_knowledge',
  status: 'failed',
  contentJson: {},
  errorMessage: String(errorMessage).slice(0, 2000),
};

return [{ json: { callbackUrl, rawBody: JSON.stringify(callbackBody) } }];
